head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods90004";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods90004.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {

};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_eClose_onclick
 * @description btn_eClose 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_eClose_onclick = function(e){
    try {
        scwin.e_close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods90004.btn_eClose_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCookie
 * @description set Cookie 처리
 * @param {*} name name
 * @param {*} value value
 * @param {*} expiredays expiredays
 * @returns {void}
 * @hidden N
 */
scwin.setCookie = function (name, value, expiredays) { $c.util.setSessionStorage(name, value); };

/**
 * @method
 * @name e_close
 * @description e close 처리
 * @returns {void}
 * @hidden N
 */
scwin.e_close = function () {
    if ($("#ipt_todayNot").is(":checked")) {
        scwin.setCookie("JLDODS90004", "JLDODS90004", 1);
    }
    $c.win.closePopup();
};
